// Nashville: Make It or Fake It: writers' rounds, a living world, texts, studio sessions, album covers, more show
// moments, love triangles, the Power 20 and rival schemes, season-finale cliffhangers, save slots and the scrapbook.

// ---------- shared helpers ----------
function ensureWorld(){S.texts=S.texts||{th:{},unread:{},pend:{}};S.npcRel=S.npcRel||{};S.book=S.book||[];S.power=S.power||[];S.jeal=S.jeal||0;S.beats=S.beats||{};S.rivalDebuff=S.rivalDebuff||0;
 if(has('beverly')&&R('beverly').tag==='')R('beverly').tag=S.char==='scarlett'?'Mother':S.char==='deacon'?'Sister':'';if(has('beverly')&&family('beverly'))R('beverly').met=1}
const castSpec=(ids,mood,set)=>({set,cam:'line',chars:ids.map(x=>typeof x==='object'?Object.assign({mood},x):{look:lookFor(x),mood:x==='me'?'happy':mood})});
const pairKey=(a,b)=>[a,b].sort().join('|');
const mini=id=>`<span class="mini-av">${id&&typeof id==='object'?portrait(id):pt(id)}</span>`;
function modal3D(html,spec,opts){modal(html,opts);mountIn($('#mbody .scene'),spec)}

// support group shots (season finales etc.) in events
(function(){const _se=window.showEvent;window.showEvent=function(e,ctx){_se(e,ctx);if(e.cast){const el=$('#mbody .scene');if(el)mountIn(el,castSpec(e.cast.concat(['me']),e.mood||'neutral',e.set||'stage'))}}})();

// ---------- 15: save slots ----------
const SLOTS=3,slotKey=i=>'nmof_slot_'+i;
UI.slot=+(()=>{try{return localStorage.getItem('nmof_cur')||1}catch(e){return 1}})();
(function(){try{if(!localStorage.getItem(slotKey(1))&&localStorage.getItem(SAVE_KEY)){localStorage.setItem(slotKey(1),localStorage.getItem(SAVE_KEY));localStorage.removeItem(SAVE_KEY)}}catch(e){}})();
window.save=function(){if(!S)return;try{localStorage.setItem(slotKey(UI.slot),JSON.stringify(S));localStorage.setItem('nmof_cur',UI.slot)}catch(e){}};
window.load=function(){try{const d=localStorage.getItem(slotKey(UI.slot));return d?JSON.parse(d):null}catch(e){return null}};
function slotData(i){try{const d=localStorage.getItem(slotKey(i));return d?JSON.parse(d):null}catch(e){return null}}
window.titleScreen=function(){const cast=['rayna','juliette','deacon','scarlett','gunnar','avery','will'];
 const slots=[1,2,3].map(i=>{const d=slotData(i);if(!d)return`<button class="slot empty" data-slot="${i}" data-new="1"><span class="slot-n">Slot ${i}</span><b>Empty</b><small>Start a new career here</small></button>`;
  return`<div class="slot"><span class="slot-av">${portrait(d.look,{mood:d.over?'sad':'happy'})}</span><span class="slot-info"><span class="slot-n">Slot ${i}</span><b>${esc(d.name)}</b><small>${d.over?'Career over':d.story&&d.story.on&&!d.story.done?`Season ${Math.min(6,seasonOf(d.week))} · Episode ${epOf(d.week)}`:'Week '+d.week} · ${num(d.fans)} fans</small></span><span class="slot-btns">${d.over?'':`<button class="mini" data-slot="${i}">Play</button>`}<button class="mini ghosty" data-slot="${i}" data-new="1">New</button></span></div>`}).join('');
 $('#app').innerHTML=`<div class="title"><div class="title-bg"></div><div class="title-stage scene" id="titleStage"><div class="fallback cast-fb">${cast.map(k=>`<span>${pt(k,'happy')}</span>`).join('')}</div></div>
 <div class="title-in"><div class="neon">Nashville</div><div class="neon2">Make It <i>or</i> Fake It</div><p class="tag-line">Music City is watching. Every hit, every heartbreak, every lie.</p>
 <div class="slots">${slots}</div><p class="faint small">A just-for-fun fan game inspired by the TV drama Nashville.</p></div></div>`;
 document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{const i=+b.dataset.slot;const go=()=>{UI.slot=i;if(b.dataset.new){S=null;chooseMode()}else{S=slotData(i);migrate();UI.tab='home';save();render()}};if(b.dataset.new&&slotData(i))confirmBox(`Overwrite slot ${i}?`,'That career will be gone for good.',go);else go()});
 view3D($('#titleStage'),{set:'stage',cam:'line',chars:cast.map(k=>({look:CHARS[k].look,mood:'happy',anim:k==='rayna'?'wave':k==='deacon'?'guitar':k==='juliette'?'perform':null,guitar:k==='deacon',mic:k==='juliette'}))},'page')};

// ---------- 15: scrapbook ----------
const MEM={firstgig:['Your first gig','street'],release:['Your first single on the radio','office'],top10:['A Top 10 hit','stage'],first1:['NUMBER ONE','stage'],album:['Your first album','home'],gold:['Gold record','carpet'],plat:['Platinum!','carpet'],bluebird:['First night at the Bluebird','bar'],opry:['Opry debut','stage'],member:['Opry member','stage'],ryman:['The Mother Church','stage'],arena:['Bridgestone Arena','stage'],stadium:['A stadium show','stage'],tour:['On the road','road'],married:['Engaged!','church'],award:['Award winner','carpet'],eoty:['Entertainer of the Year','carpet'],rehab:['A second chance','hospital'],out:['Living out loud','press'],hof:['Hall of Fame','carpet'],guest:['A surprise duet','stage'],exposed:['Exposed','press'],newlook:['A brand-new look','home'],cover:['Cover story','press'],label:['Signed!','office'],ownlabel:['Your own label','office'],love:['Falling in love','home'],round:['Won a writers\' round','bar'],sober:['One year sober','church']};
function addMemory(cap,set,cast,mood){ensureWorld();S.book.push({wk:S.week,cap,set:set||'stage',cast:cast||['me'],mood:mood||'happy'});if(S.book.length>80)S.book.shift()}
(function(){const _a=window.ach;window.ach=function(k){const had=S&&S.ach&&S.ach[k];_a(k);if(S&&k==='album')setTimeout(coverPrompt,120);if(!S||had||!MEM[k])return;const cast=['me'];if(k==='married'||k==='love'){if(S.partner&&has(S.partner))cast.unshift(S.partner)}if(k==='guest'){}addMemory(MEM[k][0],MEM[k][1],cast,k==='exposed'||k==='rehab'?'sad':'happy')}})();
function bookPanel(){ensureWorld();if(!S.book.length)return`<section class="card"><h3>Scrapbook</h3><p class="muted">Your big moments will be saved here: first gigs, #1 hits, weddings, awards, scandals.</p></section>`;
 return`<section class="card"><h3>Scrapbook</h3><p class="small muted">${S.book.length} memories. Tap one to relive it.</p><div class="polaroids">${S.book.slice().reverse().map((m,i)=>`<button class="polaroid" data-mem="${S.book.length-1-i}" style="--r:${((i*37)%9)-4}deg">${mini(m.cast[0])}<b>${esc(m.cap)}</b><small>${dateStr(m.wk)}</small></button>`).join('')}</div></section>`}
function openMemory(i){const m=S.book[i];if(!m)return;const nav=`<div class="mfoot"><button class="ghost" data-mprev ${i<=0?'disabled':''}>◂ Earlier</button><button class="ghost" data-x>Close</button><button class="ghost" data-mnext ${i>=S.book.length-1?'disabled':''}>Later ▸</button></div>`;
 modal3D(`<div class="memory">${sceneBox('wide',pt(m.cast[0]==='me'?'me':m.cast[0],m.mood))}<span class="eyebrow">${dateStr(m.wk)}${S.story&&S.story.on?` · Season ${Math.min(6,seasonOf(m.wk))}, Episode ${epOf(m.wk)}`:''}</span><h2>${esc(m.cap)}</h2></div>${nav}`,m.cast.length>1?castSpec(m.cast,m.mood,m.set):{set:m.set,cam:'full',drag:true,chars:[{look:lookFor(m.cast[0]),mood:m.mood,anim:m.mood==='happy'?'wave':null}]},
  {onClick:e=>{if(e.target.closest('[data-x]'))closeModal();if(e.target.closest('[data-mprev]'))openMemory(i-1);if(e.target.closest('[data-mnext]'))openMemory(i+1)}})}

