function livingWorld(silent){ensureWorld();for(const b of BEATS){if(S.beats[b.id]||S.week<b.at)continue;if(b.need.some(k=>!has(k)))continue;if(b.when&&!b.when())continue;S.beats[b.id]=1;news(b.news,'big');if(b.fx)b.fx();if(!silent&&b.ev){const ev=b.ev();if(ev){ev.id='beat_'+b.id;ev.sys=1;ev.tag=ev.tag||'Around town';UI.queue.push({id:ev.id,ev})}}break}
 if(silent||!chance(.22))return;const A=ADULT_NPCS(),pairs=Object.entries(S.npcRel);const r=Math.random();
 const free=k=>k!==S.partner&&!R(k).dating&&!pairs.some(([key,v])=>key.split('|').includes(k)&&(v.t==='dating'||v.t==='married'));
 if(r<.3){const c1=pick(A.filter(free));const c2=c1&&pick(A.filter(k=>k!==c1&&free(k)&&canRomance(k)&&canRomance(c1)&&CHARS[k].look.g!==CHARS[c1].look.g));if(c1&&c2){S.npcRel[pairKey(c1,c2)]={t:'dating',wk:S.week};news(`${fullnm(c1)} and ${fullnm(c2)} are dating, sources confirm`);post(c1,`Can't stop smiling. That's all. 💕`);if(R(c1).r>=30||R(c2).r>=30){const w=R(c1).r>=30?c1:c2;FX.st(4);log(`${nm(w)} is dating someone else now. Ouch.`,'bad')}}}
 else if(r<.45){const d=pairs.filter(([k,v])=>v.t==='dating');if(d.length){const[k]=pick(d);const[a,b]=k.split('|');delete S.npcRel[k];news(`${fullnm(a)} and ${fullnm(b)} split`,'bad');post(a,'Some songs write themselves.')}}
 else if(r<.55){const d=pairs.filter(([k,v])=>v.t==='dating'&&S.week-v.wk>15);if(d.length){const[k,v]=pick(d);v.t='married';const[a,b]=k.split('|');news(`${fullnm(a)} and ${fullnm(b)} tie the knot`,'big')}}
 else if(r<.75){const s=A.filter(k=>CHARS[k].singer);const a=pick(s),b=pick(s.filter(k=>k!==a));if(a&&b&&!S.npcRel[pairKey(a,b)]){S.npcRel[pairKey(a,b)]={t:'feud',wk:S.week};news(`Feud alert: ${fullnm(a)} and ${fullnm(b)} trade insults online`,'bad');post(a,pick(RIVAL_LINES))}}
 else if(r<.85){const f=pairs.filter(([k,v])=>v.t==='feud');if(f.length){const[k]=pick(f);delete S.npcRel[k];const[a,b]=k.split('|');news(`${fullnm(a)} and ${fullnm(b)} bury the hatchet`)}}
 else{const s=A.filter(k=>CHARS[k].singer);const a=pick(s),b=pick(s.filter(k=>k!==a));if(a&&b){const t=genTitle();S.npcSongs.push({artist:`${fullnm(a)} & ${fullnm(b)}`,id:a,title:t,base:(npcFame(a)+npcFame(b))*.75,w:1,pts:20});news(`${fullnm(a)} and ${fullnm(b)} release a duet: "${t}"`)}}}
