function suitors(){return Object.keys(S.rel).filter(k=>has(k)&&canRomance(k)&&k!==S.partner&&R(k).r>=35)}
function triangleCard(){const sx=suitors();if(!sx.length||(!S.partner&&sx.length<2))return'';const a=S.partner&&has(S.partner)?S.partner:sx[1],b=sx[0];
 return`<section class="card tri"><span class="eyebrow">Love triangle</span><div class="tri-row">${mini(a)}<span class="tri-me">${mini('me')}</span>${mini(b)}</div><div class="tri-names"><span>${esc(nm(a))} ♥ ${R(a).r}</span><span>${esc(nm(b))} ♥ ${R(b).r}</span></div>${S.partner?meter('Jealousy',S.jeal,S.jeal>60?'bad':'amber'):''}<p class="small muted">${S.jeal>60?`${esc(nm(S.partner))} is about to give you an ultimatum.`:S.partner?`${esc(nm(S.partner))} has noticed how you look at ${esc(nm(b))}.`:'Two hearts, one decision.'}</p></section>`}
