const TEASE={w_jdrop:'A superstar falls.',w_jh65:'Old rivals, new label.',w_lukeprop:'A ring at the Ryman.',w_jawed:'A secret wedding.',w_layla2:'Someone ends up in the hospital.',w_liver:'A legend needs a miracle.',w_baby:'A baby on the way.',w_reunite:'Twenty years late.',w_plane:'A plane goes down.',w_willout:'The truth comes out.',w_wed:'A backyard wedding.',w_jeff:'A fall from a balcony.',w_maddie:'A daughter declares war.',w_zach:'A billionaire wants in.',w_stalk:'A letter with no stamp.',w_goodbye:'Nashville will never be the same.',w_famtour:'The family hits the road.',w_finale:'One last night at the Ryman.',w_nomparty:'Champagne and knives.',w_bbanniv:'The Bluebird celebrates.',w_opry90:'The Opry turns another year older.',w_jpost:'Darkness after the light.',w_teddyarrest:'Handcuffs on live TV.',w_custody:'A custody war.',w_scargun:'Two voices, one record.',w_daphne:'A star is born on TV.',w_bar:'A new bar on Broadway.',w_peggy:'Someone says yes.',w_jessie:'A new face for an old heart.',w_cash:'A dangerous new friend.',w_exes:'A band is born.',w_mayor:'An election.',w_crash:'Headlights in the rain.'};

