(function(){const _se=window.seasonEnd;window.seasonEnd=function(s){const ev=_se(s);const cast=Object.keys(S.rel).filter(has).sort((a,b)=>Math.abs(R(b).a)+R(b).r-Math.abs(R(a).a)-R(a).r).slice(0,4);ev.cast=cast;ev.set='stage';
 if(s<SEASONS){const next=WORLD.filter(w=>seasonOf(w.at)===s+1&&TEASE[w.id]).slice(0,4).map(w=>TEASE[w.id]);const cliff=pick(['As the credits roll, your phone lights up with a number you haven\'t seen in years.','Somewhere across town, someone is writing a song about you. It isn\'t kind.','A black car has been parked outside your house for three nights.','Your manager calls at midnight: "Are you sitting down?"','An envelope arrives with no return address. Inside: a photo of you.']);
  ev.text=`<div class="finale-banner">SEASON ${s} FINALE</div>`+ev.text+`<br><br><i>${cliff}</i><div class="nexttime"><b>Next time on Nashville…</b>${next.map(t=>`<span>${esc(t)}</span>`).join('')}</div>`}
 addMemory(`Season ${s} finale`,'stage',cast.slice(0,2).concat(['me']),'happy');return ev}})();

