const _stage3=VIEWS.stage;VIEWS.stage=function(){const h=_stage3();if(UI.sub.stage!=='venues')return h;const i=h.indexOf('<section class="card venue');const card=`<section class="card round-card"><div class="between"><div><span class="eyebrow">Playable</span><h3>Bluebird writers' round</h3><p class="small muted">Sit in the circle with three other writers. Pick your songs and how you play them. Win the room and someone important might be listening.</p></div><button class="mini" data-round="1" ${S.tour?'disabled':''}>Play</button></div></section>`;return i>0?h.slice(0,i)+card+h.slice(i):card+h};
const _people3=VIEWS.people;VIEWS.people=function(){const h=_people3();const i=h.indexOf('<div class="seg">');const extra=triangleCard()+aroundTown();return i>0?h.slice(0,i)+extra+h.slice(i):h+extra};
const _media3=VIEWS.media;VIEWS.media=function(){const sub=UI.sub.media;let h=_media3();h=h.replace('<div class="seg">',`<div class="seg"><button class="${sub==='power'?'on':''}" data-sub="media:power">Power 20</button>`);if(sub==='power')h+=powerPanel();return h};
const _life3=VIEWS.life;VIEWS.life=function(){const sub=UI.sub.life;let h=_life3();h=h.replace('<div class="seg">',`<div class="seg"><button class="${sub==='book'?'on':''}" data-sub="life:book">📸 Scrapbook</button>`);if(sub==='book')h+=bookPanel();return h};
const _music3=VIEWS.music;VIEWS.music=function(){let h=_music3();if(UI.sub.music==='release'&&S.albums.length){h+=`<section class="card"><h3>Album shelf</h3><div class="shelf">${S.albums.slice().reverse().map(a=>`<button class="shelf-item" data-cover="${a.id}">${coverHTML(a)}<small>${esc(a.title)}${a.cert?' · '+a.cert:''}</small></button>`).join('')}</div><p class="small faint">Tap an album to redesign its cover.</p></section>`}if(S.flags.coverPending)h=`<section class="card mof"><b>Your new album needs a cover!</b> <button class="mini" data-cover="${S.flags.coverPending}">Design it</button></section>`+h;return h};
(function(){const _r=window.render;window.render=function(){_r();if(!S||S.over)return;const tin=$('.top-in');if(tin&&!$('.phone-btn')){const u=unreadCount();tin.querySelector('.top-stats').insertAdjacentHTML('beforebegin',`<button class="phone-btn" data-phone="1" aria-label="Messages">📱${u?`<em>${u}</em>`:''}</button>`)}}})();
document.addEventListener('click',e=>{if(!S||S.over||e.target.closest('#modal'))return;let el;
 if(el=e.target.closest('[data-phone]'))return openPhone();if(el=e.target.closest('[data-round]'))return startRound();if(el=e.target.closest('[data-scheme]'))return doScheme(el.dataset.scheme);
 if(el=e.target.closest('[data-mem]'))return openMemory(+el.dataset.mem);if(el=e.target.closest('[data-cover]'))return openCover(+el.dataset.cover)});
